export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isComment = (c) => c === '#' || c === ';'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

const newTable = () => ({ t: 'table', type: 'table', map: new Map(), explicit: false })

class LineParser {
  constructor(s, lineNo) {
    this.s = s
    this.i = 0
    this.n = lineNo
  }
  fail(msg) {
    throw new ParseError(msg, this.n)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  /** True at end of line or at the start of a comment. */
  atEnd() {
    return this.i >= this.s.length || isComment(this.s[this.i])
  }
  string() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) this.fail('unterminated string')
      const c = this.s[this.i++]
      if (c === q) return out
      if (q === "'" || c !== '\\') {
        out += c
        continue
      }
      if (this.i >= this.s.length) this.fail('unterminated string')
      const e = this.s[this.i++]
      if (e === '"' || e === '\\') out += e
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else this.fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0) ?? 0) + (e.length > 1 && !(e.codePointAt(0) > 0xffff) ? '' : ''))
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (this.i === st) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }
