    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') {
        this.i = save
        return names
      }
      this.i++
      this.ws()
      names.push(this.name())
    }
  }
  value(prefix) {
    this.ws()
    const c = this.s[this.i]
    if (this.atEnd() || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"' || c === "'") return { t: 's', type: 'string', v: this.string() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
