        this.i++
        return { t: 'array', type: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.s[this.i] === ',') this.i++
      else if (this.s[this.i] !== ']') this.fail('unterminated array')
    }
