const pathOf = (p) => p.join('.')

/** Walk from `table` through `names` (all but possibly creating), returning the table reached. */
function walk(table, base, names, p) {
  let cur = table
  for (let k = 0; k < names.length; k++) {
    let next = cur.map.get(names[k])
    if (!next) {
      next = newTable()
      cur.map.set(names[k], next)
    } else if (next.t === 'array' && next.aot) next = next.items[next.items.length - 1]
    else if (next.t !== 'table') p.fail(pathOf([...base, ...names.slice(0, k + 1)]) + ' is not a table')
    cur = next
  }
  return cur
}

function assign(table, base, names, value, p) {
  const parent = walk(table, base, names.slice(0, -1), p)
  const last = names[names.length - 1]
  if (parent.map.has(last)) p.fail('key ' + pathOf([...base, ...names]) + ' is defined twice')
  parent.map.set(last, value)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let curPath = []
  lines.forEach((line, idx) => {
    const p = new LineParser(line, idx + 1)
    p.ws()
    if (p.atEnd()) return
    if (line[p.i] === '[') {
      p.i++
      const aot = line[p.i] === '['
      if (aot) p.i++
      p.ws()
      const names = p.dotted()
      p.ws()
      if (p.atEnd() && p.i >= line.length || p.atEnd()) p.fail('unterminated table header')
      if (line[p.i] !== ']') p.fail('unterminated table header')
      p.i++
      if (aot) {
        if (line[p.i] !== ']') p.fail('unterminated table header')
        p.i++
      }
      p.ws()
      if (!p.atEnd()) p.fail('trailing text after a table header')
      const parent = walk(root, [], names.slice(0, -1), p)
      const last = names[names.length - 1]
      const full = pathOf(names)
      const ex = parent.map.get(last)
      if (aot) {
        if (!ex) {
          const arr = { t: 'array', type: 'array', items: [], aot: true }
          parent.map.set(last, arr)
          current = newTable()
          arr.items.push(current)
        } else if (ex.t === 'array' && ex.aot) {
          current = newTable()
          ex.items.push(current)
        } else p.fail(full + ' is not an array of tables')
      } else if (!ex) {
        current = newTable()
        current.explicit = true
        parent.map.set(last, current)
      } else if (ex.t !== 'table') p.fail(full + ' is not a table')
      else if (ex.explicit) p.fail('table ' + full + ' is defined twice')
      else {
        ex.explicit = true
        current = ex
      }
      curPath = names
      return
    }
    const names = p.dotted()
    p.ws()
    if (line[p.i] !== '=') p.fail('expected key = value')
    p.i++
    const v = p.value([...curPath, ...names])
    p.ws()
    if (!p.atEnd()) p.fail('trailing text after a value')
    assign(current, curPath, names, v, p)
  })
  return root
}
